package com.universalplatform.integration;
import java.net.URI; import java.net.http.*; import java.time.*; import java.util.*; import org.springframework.data.domain.PageRequest; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*;
@Service class WebhookWorker { private final WebhookDeliveryRepository deliveries; private final WebhookSubscriptionRepository subs; private final IntegrationSecretCipher cipher; private final java.net.http.HttpClient http=HttpClient.newHttpClient(); private final Clock clock=Clock.systemUTC(); WebhookWorker(WebhookDeliveryRepository d,WebhookSubscriptionRepository s,IntegrationSecretCipher c){deliveries=d;subs=s;cipher=c;} @Scheduled(fixedDelayString="${platform.integrations.webhooks.poll-ms:2000}") void poll(){Instant n=clock.instant();for(UUID id:deliveries.findDue(n,PageRequest.of(0,25)))deliver(id);} @Transactional(propagation=Propagation.REQUIRES_NEW) void deliver(UUID id){WebhookDelivery d=deliveries.lock(id).orElse(null);if(d==null||d.deliveredAt()!=null)return;WebhookSubscription s=subs.findById(d.subscriptionId()).orElse(null);if(s==null||!s.enabled()){d.failed("Subscription unavailable",clock.instant());return;}try{long epoch=clock.instant().getEpochSecond();String sig=WebhookService.signature(cipher.decrypt(s.secretCiphertext()),epoch,d.payloadJson());HttpRequest r=HttpRequest.newBuilder(URI.create(s.callbackUrl())).timeout(Duration.ofSeconds(15)).header("Content-Type","application/json").header("X-UEP-Event-ID",d.eventId().toString()).header("X-UEP-Event",d.eventType()).header("X-UEP-Signature","t="+epoch+",v1="+sig).POST(HttpRequest.BodyPublishers.ofString(d.payloadJson())).build();HttpResponse<Void> response=http.send(r,HttpResponse.BodyHandlers.discarding());if(response.statusCode()/100!=2)throw new IllegalStateException("Webhook HTTP "+response.statusCode());d.success(clock.instant());s.delivered(clock.instant());}catch(Exception e){d.failed(e.getMessage(),clock.instant());s.failed(clock.instant(),e.getMessage());}} }
